import {useEffect,useState} from "react";export type SaveStatus="pending"|"saved"|"error";export function useAutosave(key:string,value:string,write:(key:string,value:string)=>void,delay=500,enabled=true){const [record,setRecord]=useState<{key:string;value:string;status:SaveStatus}>(()=>({key,value,status:"pending"}));useEffect(()=>{if(!enabled||!Number.isSafeInteger(delay)||delay<0||delay>2147483647){setRecord({key,value,status:"error"});return;}setRecord({key,value,status:"pending"});const id=setTimeout(()=>{try{write(key,value);setRecord({key,value,status:"saved"});}catch{setRecord({key,value,status:"error"});}},delay);return ()=>clearTimeout(id);},[key,value,write,delay,enabled]);return record.key===key&&record.value===value?record.status:"pending";}
